     1→// Package settings provides configuration loading for Entire.
     2→// This package is separate from cli to allow strategy package to import it
     3→// without creating an import cycle (cli imports strategy).
     4→package settings
     5→
     6→import (
     7→	"encoding/json"
     8→	"fmt"
     9→	"os"
    10→
    11→	"github.com/entireio/cli/cmd/entire/cli/paths"
    12→)
    13→
    14→// DefaultStrategyName is the default strategy when none is configured.
    15→// This is duplicated here to avoid importing the strategy package (which would create a cycle).
    16→const DefaultStrategyName = "manual-commit"
    17→
    18→const (
    19→	// EntireSettingsFile is the path to the Entire settings file
    20→	EntireSettingsFile = ".entire/settings.json"
    21→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
    22→	EntireSettingsLocalFile = ".entire/settings.local.json"
    23→)
    24→
    25→// EntireSettings represents the .entire/settings.json configuration
    26→type EntireSettings struct {
    27→	// Strategy is the name of the git strategy to use
    28→	Strategy string `json:"strategy"`
    29→
    30→	// Enabled indicates whether Entire is active. When false, CLI commands
    31→	// show a disabled message and hooks exit silently. Defaults to true.
    32→	Enabled bool `json:"enabled"`
    33→
    34→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
    35→	// This is used for development when the binary is not installed
    36→	LocalDev bool `json:"local_dev,omitempty"`
    37→
    38→	// LogLevel sets the logging verbosity (debug, info, warn, error).
    39→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
    40→	// Defaults to "info".
    41→	LogLevel string `json:"log_level,omitempty"`
    42→
    43→	// StrategyOptions contains strategy-specific configuration
    44→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
    45→
    46→	// Telemetry controls anonymous usage analytics.
    47→	// nil = not asked yet (show prompt), true = opted in, false = opted out
    48→	Telemetry *bool `json:"telemetry,omitempty"`
    49→}
    50→
    51→// Load loads the Entire settings from .entire/settings.json,
    52→// then applies any overrides from .entire/settings.local.json if it exists.
    53→// Returns default settings if neither file exists.
    54→// Works correctly from any subdirectory within the repository.
    55→func Load() (*EntireSettings, error) {
    56→	// Get absolute paths for settings files
    57→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
    58→	if err != nil {
    59→		settingsFileAbs = EntireSettingsFile // Fallback to relative
    60→	}
    61→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
    62→	if err != nil {
    63→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
    64→	}
    65→
    66→	// Load base settings
    67→	settings, err := loadFromFile(settingsFileAbs)
    68→	if err != nil {
    69→		return nil, fmt.Errorf("reading settings file: %w", err)
    70→	}
    71→
    72→	// Apply local overrides if they exist
    73→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
    74→	if err != nil {
    75→		if !os.IsNotExist(err) {
    76→			return nil, fmt.Errorf("reading local settings file: %w", err)
    77→		}
    78→		// Local file doesn't exist, continue without overrides
    79→	} else {
    80→		if err := mergeJSON(settings, localData); err != nil {
    81→			return nil, fmt.Errorf("merging local settings: %w", err)
    82→		}
    83→	}
    84→
    85→	applyDefaults(settings)
    86→
    87→	return settings, nil
    88→}
    89→
    90→// loadFromFile loads settings from a specific file path.
    91→// Returns default settings if the file doesn't exist.
    92→func loadFromFile(filePath string) (*EntireSettings, error) {
    93→	settings := &EntireSettings{
    94→		Strategy: DefaultStrategyName,
    95→		Enabled:  true, // Default to enabled
    96→	}
    97→
    98→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
    99→	if err != nil {
   100→		if os.IsNotExist(err) {
   101→			return settings, nil
   102→		}
   103→		return nil, fmt.Errorf("%w", err)
   104→	}
   105→
   106→	if err := json.Unmarshal(data, settings); err != nil {
   107→		return nil, fmt.Errorf("parsing settings file: %w", err)
   108→	}
   109→	applyDefaults(settings)
   110→
   111→	return settings, nil
   112→}
   113→
   114→// mergeJSON merges JSON data into existing settings.
   115→// Only non-zero values from the JSON override existing settings.
   116→func mergeJSON(settings *EntireSettings, data []byte) error {
   117→	// Parse into a map to check which fields are present
   118→	var raw map[string]json.RawMessage
   119→	if err := json.Unmarshal(data, &raw); err != nil {
   120→		return fmt.Errorf("parsing JSON: %w", err)
   121→	}
   122→
   123→	// Override strategy if present and non-empty
   124→	if strategyRaw, ok := raw["strategy"]; ok {
   125→		var s string
   126→		if err := json.Unmarshal(strategyRaw, &s); err != nil {
   127→			return fmt.Errorf("parsing strategy field: %w", err)
   128→		}
   129→		if s != "" {
   130→			settings.Strategy = s
   131→		}
   132→	}
   133→
   134→	// Override enabled if present
   135→	if enabledRaw, ok := raw["enabled"]; ok {
   136→		var e bool
   137→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
   138→			return fmt.Errorf("parsing enabled field: %w", err)
   139→		}
   140→		settings.Enabled = e
   141→	}
   142→
   143→	// Override local_dev if present
   144→	if localDevRaw, ok := raw["local_dev"]; ok {
   145→		var ld bool
   146→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
   147→			return fmt.Errorf("parsing local_dev field: %w", err)
   148→		}
   149→		settings.LocalDev = ld
   150→	}
   151→
   152→	// Override log_level if present and non-empty
   153→	if logLevelRaw, ok := raw["log_level"]; ok {
   154→		var ll string
   155→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
   156→			return fmt.Errorf("parsing log_level field: %w", err)
   157→		}
   158→		if ll != "" {
   159→			settings.LogLevel = ll
   160→		}
   161→	}
   162→
   163→	// Merge strategy_options if present
   164→	if optionsRaw, ok := raw["strategy_options"]; ok {
   165→		var opts map[string]any
   166→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
   167→			return fmt.Errorf("parsing strategy_options field: %w", err)
   168→		}
   169→		if settings.StrategyOptions == nil {
   170→			settings.StrategyOptions = opts
   171→		} else {
   172→			for k, v := range opts {
   173→				settings.StrategyOptions[k] = v
   174→			}
   175→		}
   176→	}
   177→
   178→	// Override telemetry if present
   179→	if telemetryRaw, ok := raw["telemetry"]; ok {
   180→		var t bool
   181→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
   182→			return fmt.Errorf("parsing telemetry field: %w", err)
   183→		}
   184→		settings.Telemetry = &t
   185→	}
   186→
   187→	return nil
   188→}
   189→
   190→func applyDefaults(settings *EntireSettings) {
   191→	if settings.Strategy == "" {
   192→		settings.Strategy = DefaultStrategyName
   193→	}
   194→}
   195→
   196→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
   197→// Returns false by default if settings cannot be loaded or the key is missing.
   198→func IsSummarizeEnabled() bool {
   199→	settings, err := Load()
   200→	if err != nil {
   201→		return false
   202→	}
   203→	return settings.IsSummarizeEnabled()
   204→}
   205→
   206→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
   207→func (s *EntireSettings) IsSummarizeEnabled() bool {
   208→	if s.StrategyOptions == nil {
   209→		return false
   210→	}
   211→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
   212→	if !ok {
   213→		return false
   214→	}
   215→	enabled, ok := summarizeOpts["enabled"].(bool)
   216→	if !ok {
   217→		return false
   218→	}
   219→	return enabled
   220→}
   221→
   222→// IsMultiSessionWarningDisabled checks if multi-session warnings are disabled.
   223→// Returns false (show warnings) by default if the key is missing.
   224→func (s *EntireSettings) IsMultiSessionWarningDisabled() bool {
   225→	if s.StrategyOptions == nil {
   226→		return false
   227→	}
   228→	if disabled, ok := s.StrategyOptions["disable_multisession_warning"].(bool); ok {
   229→		return disabled
   230→	}
   231→	return false
   232→}
