// Package filter provides content filtering through external commands.
// Used to redact sensitive data (like API keys, secrets) from session transcripts.
package filter

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// FilterTimeout is the maximum time allowed for filter command execution.
const FilterTimeout = 30 * time.Second

// ErrFilterNotFound is returned when the filter command executable cannot be found.
var ErrFilterNotFound = errors.New("output filter command not found")

// ErrFilterFailed is returned when the filter command returns a non-zero exit code.
var ErrFilterFailed = errors.New("output filter failed")

// ErrFilterTimeout is returned when the filter command exceeds the timeout.
var ErrFilterTimeout = errors.New("output filter timed out")

// FilterContent pipes content through the configured filter command.
// Returns original content if no filter is configured.
// Returns error if filter is configured but fails (command not found, non-zero exit, timeout).
//
// The filename parameter is provided for context (e.g., logging) but is not passed
// to the filter command. The filter receives content on stdin and writes to stdout.
func FilterContent(ctx context.Context, content []byte, filename string) ([]byte, error) {
	_ = filename // Reserved for future use (logging, conditional filtering)

	filterCmd := settings.GetOutputFilter()
	if len(filterCmd) == 0 {
		// No filter configured, return original content
		return content, nil
	}

	return runFilter(ctx, content, filterCmd)
}

// runFilter executes the filter command with the given content on stdin.
func runFilter(ctx context.Context, content []byte, filterCmd []string) ([]byte, error) {
	// Create context with timeout
	ctx, cancel := context.WithTimeout(ctx, FilterTimeout)
	defer cancel()

	// Build the command
	//nolint:gosec // filterCmd is from trusted settings file
	cmd := exec.CommandContext(ctx, filterCmd[0], filterCmd[1:]...)
	cmd.Stdin = bytes.NewReader(content)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	// Run the command
	err := cmd.Run()
	if err != nil {
		// Check for timeout
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return nil, fmt.Errorf("%w after %s", ErrFilterTimeout, FilterTimeout)
		}

		// Check for command not found
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return nil, fmt.Errorf("%w: %q", ErrFilterNotFound, filterCmd[0])
		}

		// Check for exit error
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			stderrStr := stderr.String()
			if len(stderrStr) > 200 {
				stderrStr = stderrStr[:200] + "..."
			}
			return nil, fmt.Errorf("%w (exit %d): %s", ErrFilterFailed, exitErr.ExitCode(), stderrStr)
		}

		// Unknown error
		return nil, fmt.Errorf("filter execution failed: %w", err)
	}

	return stdout.Bytes(), nil
}

// MustFilter is like FilterContent but panics on error.
// Use only in contexts where filter failure is truly unrecoverable.
func MustFilter(ctx context.Context, content []byte, filename string) []byte {
	filtered, err := FilterContent(ctx, content, filename)
	if err != nil {
		panic(fmt.Sprintf("filter failed for %s: %v", filename, err))
	}
	return filtered
}

package filter

import (
	"bytes"
	"context"
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestFilterContent_NoFilter(t *testing.T) {
	// When no filter is configured (settings return nil), content passes through unchanged
	content := []byte("sensitive data: api_key=sk-12345")

	result, err := FilterContent(context.Background(), content, "test.txt")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !bytes.Equal(result, content) {
		t.Errorf("expected content to pass through unchanged, got %q", result)
	}
}

func TestRunFilter_Success(t *testing.T) {
	// Test with cat - should pass content through unchanged
	content := []byte("hello world")

	result, err := runFilter(context.Background(), content, []string{"cat"})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !bytes.Equal(result, content) {
		t.Errorf("expected %q, got %q", content, result)
	}
}

func TestRunFilter_WithArgs(t *testing.T) {
	// Test with sed - should transform content
	content := []byte("secret_key")

	result, err := runFilter(context.Background(), content, []string{"sed", "s/secret/REDACTED/"})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	expected := []byte("REDACTED_key")
	if !bytes.Equal(result, expected) {
		t.Errorf("expected %q, got %q", expected, result)
	}
}

func TestRunFilter_CommandNotFound(t *testing.T) {
	content := []byte("test")

	_, err := runFilter(context.Background(), content, []string{"nonexistent-filter-command-xyz"})
	if err == nil {
		t.Fatal("expected error for nonexistent command")
	}

	if !errors.Is(err, ErrFilterNotFound) {
		t.Errorf("expected ErrFilterNotFound, got: %v", err)
	}
}

func TestRunFilter_NonZeroExit(t *testing.T) {
	content := []byte("test")

	// Use sh -c "exit 1" to simulate a failed command
	_, err := runFilter(context.Background(), content, []string{"sh", "-c", "echo error >&2; exit 1"})
	if err == nil {
		t.Fatal("expected error for non-zero exit")
	}

	if !errors.Is(err, ErrFilterFailed) {
		t.Errorf("expected ErrFilterFailed, got: %v", err)
	}
}

func TestRunFilter_Timeout(t *testing.T) {
	// Skip in short mode as this test takes time
	if testing.Short() {
		t.Skip("skipping timeout test in short mode")
	}

	content := []byte("test")

	// Create a context with a very short timeout
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()

	// sleep command will exceed our timeout
	_, err := runFilter(ctx, content, []string{"sleep", "10"})
	if err == nil {
		t.Fatal("expected error for timeout")
	}

	if !errors.Is(err, ErrFilterTimeout) {
		t.Errorf("expected ErrFilterTimeout, got: %v", err)
	}
}

func TestRunFilter_LargeContent(t *testing.T) {
	// Test with larger content to ensure piping works correctly
	content := bytes.Repeat([]byte("x"), 1024*1024) // 1MB

	result, err := runFilter(context.Background(), content, []string{"cat"})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !bytes.Equal(result, content) {
		t.Errorf("content mismatch for large input")
	}
}

func TestRunFilter_EmptyContent(t *testing.T) {
	content := []byte{}

	result, err := runFilter(context.Background(), content, []string{"cat"})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(result) != 0 {
		t.Errorf("expected empty result, got %q", result)
	}
}

func TestRunFilter_MultilineContent(t *testing.T) {
	content := []byte("line1\nline2\nline3\n")

	result, err := runFilter(context.Background(), content, []string{"cat"})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !bytes.Equal(result, content) {
		t.Errorf("expected %q, got %q", content, result)
	}
}

func TestRunFilter_ScriptFilter(t *testing.T) {
	// Create a temporary script that acts as a filter
	tmpDir := t.TempDir()
	scriptPath := filepath.Join(tmpDir, "filter.sh")

	script := `#!/bin/sh
sed 's/api_key=[^[:space:]]*/api_key=REDACTED/g'
`
	if err := os.WriteFile(scriptPath, []byte(script), 0o755); err != nil {
		t.Fatalf("failed to write script: %v", err)
	}

	content := []byte("config: api_key=sk-12345 other=value")

	result, err := runFilter(context.Background(), content, []string{scriptPath})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	expected := []byte("config: api_key=REDACTED other=value")
	if !bytes.Equal(result, expected) {
		t.Errorf("expected %q, got %q", expected, result)
	}
}

